def _positive_quads(g, mesh, index, pos):
    """Check all four planar corner Jacobians without triangulating a face."""
    corners = []
    for corner in range(4):
        c = g.node('GeometryNodeCornersOfFace', 'Quad corner '+str(corner))
        g.set(index, c.inputs['Face Index'])
        c.inputs['Sort Index'].default_value = corner
        v = g.node('GeometryNodeVertexOfCorner', 'Quad vertex '+str(corner))
        g.set(c.outputs['Corner Index'], v.inputs['Corner Index'])
        corners.append(g.sample(mesh, pos, v.outputs['Vertex Index'], 'FLOAT_VECTOR'))
    checks = []
    for corner in range(4):
        a, b, c = [corners[(corner+j)%4] for j in range(3)]
        cross = g.vector('CROSS_PRODUCT', g.vector('SUBTRACT', b, a), g.vector('SUBTRACT', c, b))
        checks.append(g.compare(g.component(cross, 'Z'), 1e-9, 'GREATER_THAN'))
    return g.stat(mesh, g.all(*checks), 'FACE')


